(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      duration: ${duration},
      size: ${size},
      fillColor: ${fillColor},
      strokeWidth: ${strokeWidth},
      strokeColor: ${strokeColor},
      bounce: ${bounce}
    };
    var layer = comp.layers.byName(p.layerName);
    if (!layer) {
      layer = comp.layers.addShape();
      layer.name = p.layerName;
    }
    var contents = layer.property("ADBE Root Vectors Group");
    var group = contents.addProperty("ADBE Vector Group");
    group.name = "Circle";
    var ellipse = group.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Ellipse");
    ellipse.property("ADBE Vector Ellipse Size").setValue([p.size, p.size]);
    var fill = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    fill.property("ADBE Vector Fill Color").setValue(p.fillColor);
    if (p.strokeWidth > 0) {
      var stroke = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
      stroke.property("ADBE Vector Stroke Color").setValue(p.strokeColor);
      stroke.property("ADBE Vector Stroke Width").setValue(p.strokeWidth);
    }
    var transform = group.property("ADBE Vector Transform Group");
    var scale = transform.property("ADBE Vector Scale");
    var t0 = layer.inPoint;
    scale.setValueAtTime(t0, [0, 0]);
    if (p.bounce) {
      scale.setValueAtTime(t0 + p.duration * 0.6, [120, 120]);
      scale.setValueAtTime(t0 + p.duration, [100, 100]);
    } else {
      scale.setValueAtTime(t0 + p.duration, [100, 100]);
    }
    for (var k = 1; k <= scale.numKeys; k++) {
      scale.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"圆形扩展动画已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      duration: ${duration},
      width: ${width},
      height: ${height},
      fillColor: ${fillColor},
      strokeWidth: ${strokeWidth},
      strokeColor: ${strokeColor},
      direction: ${direction},
      cornerRadius: ${cornerRadius}
    };
    var layer = comp.layers.byName(p.layerName);
    if (!layer) {
      layer = comp.layers.addShape();
      layer.name = p.layerName;
    }
    var contents = layer.property("ADBE Root Vectors Group");
    var group = contents.addProperty("ADBE Vector Group");
    group.name = "Rect";
    var rect = group.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Rect");
    rect.property("ADBE Vector Rect Size").setValue([p.width, p.height]);
    rect.property("ADBE Vector Rect Roundness").setValue(p.cornerRadius);
    var fill = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    fill.property("ADBE Vector Fill Color").setValue(p.fillColor);
    if (p.strokeWidth > 0) {
      var stroke = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
      stroke.property("ADBE Vector Stroke Color").setValue(p.strokeColor);
      stroke.property("ADBE Vector Stroke Width").setValue(p.strokeWidth);
    }
    var transform = layer.property("ADBE Transform Group");
    var pos = transform.property("ADBE Position");
    var t0 = layer.inPoint;
    var startPos = [comp.width/2, comp.height/2];
    var endPos = [comp.width/2, comp.height/2];
    if (p.direction === "left") startPos = [comp.width + p.width/2, comp.height/2];
    else if (p.direction === "right") startPos = [-p.width/2, comp.height/2];
    else if (p.direction === "top") startPos = [comp.width/2, comp.height + p.height/2];
    else if (p.direction === "bottom") startPos = [comp.width/2, -p.height/2];
    pos.setValueAtTime(t0, startPos);
    pos.setValueAtTime(t0 + p.duration, endPos);
    for (var k = 1; k <= pos.numKeys; k++) {
      pos.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"矩形滑入动画已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      duration: ${duration},
      size: ${size},
      fillColor: ${fillColor},
      strokeWidth: ${strokeWidth},
      strokeColor: ${strokeColor},
      repeaterCount: ${repeaterCount},
      rotationCount: ${rotationCount}
    };
    var layer = comp.layers.byName(p.layerName);
    if (!layer) {
      layer = comp.layers.addShape();
      layer.name = p.layerName;
    }
    var contents = layer.property("ADBE Root Vectors Group");
    var group = contents.addProperty("ADBE Vector Group");
    group.name = "Triangle";
    var polystar = group.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Star");
    polystar.property("ADBE Vector Star Type").setValue(2);
    polystar.property("ADBE Vector Star Points").setValue(3);
    polystar.property("ADBE Vector Star Outer Radius").setValue(p.size / 2);
    polystar.property("ADBE Vector Star Inner Radius").setValue(p.size / 4);
    var fill = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    fill.property("ADBE Vector Fill Color").setValue(p.fillColor);
    if (p.strokeWidth > 0) {
      var stroke = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
      stroke.property("ADBE Vector Stroke Color").setValue(p.strokeColor);
      stroke.property("ADBE Vector Stroke Width").setValue(p.strokeWidth);
    }
    if (p.repeaterCount > 1) {
      var repeater = group.property("ADBE Vectors Group").addProperty("ADBE Vector Filter - Repeater");
      repeater.property("ADBE Vector Repeater Copies").setValue(p.repeaterCount);
      repeater.property("ADBE Vector Repeater Rotation").setValue(360 / p.repeaterCount);
    }
    var transform = group.property("ADBE Vector Transform Group");
    var rot = transform.property("ADBE Vector Rotation");
    var scale = transform.property("ADBE Vector Scale");
    var t0 = layer.inPoint;
    rot.setValueAtTime(t0, 0);
    rot.setValueAtTime(t0 + p.duration, 360 * p.rotationCount);
    scale.setValueAtTime(t0, [0, 0]);
    scale.setValueAtTime(t0 + p.duration * 0.7, [110, 110]);
    scale.setValueAtTime(t0 + p.duration, [100, 100]);
    for (var k = 1; k <= rot.numKeys; k++) {
      rot.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    for (var k = 1; k <= scale.numKeys; k++) {
      scale.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"三角形旋转动画已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

