(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      duration: ${duration},
      strokeWidth: ${strokeWidth},
      strokeColor: ${strokeColor},
      startPoint: ${startPoint},
      endPoint: ${endPoint},
      curved: ${curved}
    };
    var layer = comp.layers.byName(p.layerName);
    if (!layer) {
      layer = comp.layers.addShape();
      layer.name = p.layerName;
    }
    var contents = layer.property("ADBE Root Vectors Group");
    var group = contents.addProperty("ADBE Vector Group");
    group.name = "Line";
    var pathGroup = group.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Group");
    var path = pathGroup.property("ADBE Vector Shape");
    var linePath = new Shape();
    linePath.vertices = [p.startPoint, p.endPoint];
    if (p.curved) {
      var midX = (p.startPoint[0] + p.endPoint[0]) / 2;
      var midY = (p.startPoint[1] + p.endPoint[1]) / 2 - 100;
      linePath.vertices = [p.startPoint, [midX, midY], p.endPoint];
      linePath.inTangents = [[0,0], [-50,0], [0,0]];
      linePath.outTangents = [[0,0], [50,0], [0,0]];
    } else {
      linePath.inTangents = [[0,0],[0,0]];
      linePath.outTangents = [[0,0],[0,0]];
    }
    linePath.closed = false;
    path.setValue(linePath);
    var stroke = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
    stroke.property("ADBE Vector Stroke Color").setValue(p.strokeColor);
    stroke.property("ADBE Vector Stroke Width").setValue(p.strokeWidth);
    stroke.property("ADBE Vector Stroke Line Cap").setValue(2);
    var trim = group.property("ADBE Vectors Group").addProperty("ADBE Vector Filter - Trim");
    var t0 = layer.inPoint;
    trim.property("ADBE Vector Trim Start").setValue(0);
    trim.property("ADBE Vector Trim End").setValueAtTime(t0, 0);
    trim.property("ADBE Vector Trim End").setValueAtTime(t0 + p.duration, 100);
    for (var k = 1; k <= trim.property("ADBE Vector Trim End").numKeys; k++) {
      trim.property("ADBE Vector Trim End").setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"线条绘制动画已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

