    group.name = "Morph";
    var pathGroup = group.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Group");
    var path = pathGroup.property("ADBE Vector Shape");
    var s = p.size / 2;
    var circlePath = new Shape();
    circlePath.vertices = [[0, -s], [s, 0], [0, s], [-s, 0]];
    circlePath.inTangents = [[-s*0.55, 0], [0, -s*0.55], [s*0.55, 0], [0, s*0.55]];
    circlePath.outTangents = [[s*0.55, 0], [0, s*0.55], [-s*0.55, 0], [0, -s*0.55]];
    circlePath.closed = true;
    path.setValueAtTime(layer.inPoint, circlePath);
    var squarePath = new Shape();
    squarePath.vertices = [[-s, -s], [s, -s], [s, s], [-s, s]];
    squarePath.inTangents = [[0,0],[0,0],[0,0],[0,0]];
    squarePath.outTangents = [[0,0],[0,0],[0,0],[0,0]];
    squarePath.closed = true;
    path.setValueAtTime(layer.inPoint + p.duration * 0.5, squarePath);
    var triPath = new Shape();
    triPath.vertices = [[0, -s], [s*0.866, s*0.5], [-s*0.866, s*0.5]];
    triPath.inTangents = [[0,0],[0,0],[0,0]];
    triPath.outTangents = [[0,0],[0,0],[0,0]];
    triPath.closed = true;
    path.setValueAtTime(layer.inPoint + p.duration, triPath);
    for (var k = 1; k <= path.numKeys; k++) {
