    stroke.property("ADBE Vector Stroke Color").setValue(p.strokeColor);
    stroke.property("ADBE Vector Stroke Width").setValue(p.strokeWidth);
    stroke.property("ADBE Vector Stroke Line Cap").setValue(2);
    if (p.dashEnabled) {
      stroke.property("ADBE Vector Stroke Dashes").addProperty("ADBE Vector Stroke Dash 1").setValue(10);
      stroke.property("ADBE Vector Stroke Dashes").addProperty("ADBE Vector Stroke Gap 1").setValue(5);
      stroke.property("ADBE Vector Stroke Dashes").addProperty("ADBE Vector Stroke Offset").expression = "time * 20";
    }
    var trim = group.property("ADBE Vectors Group").addProperty("ADBE Vector Filter - Trim");
    var t0 = layer.inPoint;
    trim.property("ADBE Vector Trim Start").setValueAtTime(t0, 50);
    trim.property("ADBE Vector Trim Start").setValueAtTime(t0 + p.duration, 0);
    trim.property("ADBE Vector Trim End").setValueAtTime(t0, 50);
    trim.property("ADBE Vector Trim End").setValueAtTime(t0 + p.duration, 100);
    for (var k = 1; k <= trim.property("ADBE Vector Trim Start").numKeys; k++) {
      trim.property("ADBE Vector Trim Start").setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"分隔线动画已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      layerName: ${layerName},
      duration: ${duration},
      bubbleCount: ${bubbleCount},
      maxSize: ${maxSize},
      fillColor: ${fillColor},
      strokeWidth: ${strokeWidth}
    };
    var layer = comp.layers.byName(p.layerName);
    if (!layer) {
      layer = comp.layers.addShape();
      layer.name = p.layerName;
    }
    var contents = layer.property("ADBE Root Vectors Group");
    for (var i = 0; i < p.bubbleCount; i++) {
      var group = contents.addProperty("ADBE Vector Group");
      group.name = "Bubble" + (i + 1);
      var size = p.maxSize * (0.4 + 0.6 * Math.random());
      var ellipse = group.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Ellipse");
      ellipse.property("ADBE Vector Ellipse Size").setValue([size, size]);
      var fill = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
      fill.property("ADBE Vector Fill Color").setValue(p.fillColor);
      if (p.strokeWidth > 0) {
        var stroke = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
        stroke.property("ADBE Vector Stroke Color").setValue([1,1,1]);
        stroke.property("ADBE Vector Stroke Width").setValue(p.strokeWidth);
      }
      var transform = group.property("ADBE Vector Transform Group");
      var startX = (Math.random() - 0.5) * comp.width * 0.8;
      var endX = startX + (Math.random() - 0.5) * 200;
      var startY = comp.height / 2 + 200;
      var endY = comp.height / 2 - 200;
      transform.property("ADBE Vector Position").setValueAtTime(layer.inPoint, [startX, startY]);
      transform.property("ADBE Vector Position").setValueAtTime(layer.inPoint + p.duration, [endX, endY]);
      var scale = transform.property("ADBE Vector Scale");
      var t0 = layer.inPoint;
      var delay = i * 0.15;
      scale.setValueAtTime(t0 + delay, [0, 0]);
      scale.setValueAtTime(t0 + delay + 0.3, [100, 100]);
      scale.setValueAtTime(t0 + p.duration * 0.8, [100, 100]);
      scale.setValueAtTime(t0 + p.duration, [0, 0]);
      for (var k = 1; k <= scale.numKeys; k++) {
        scale.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
      }
    }
    _result = {status:"success", message:"气泡弹出动画已应用"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

