    ellipse.property("ADBE Vector Ellipse Size").setValue([p.size, p.size]);
    var fill = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    fill.property("ADBE Vector Fill Color").setValue(p.fillColor);
    if (p.strokeWidth > 0) {
      var stroke = group.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Stroke");
      stroke.property("ADBE Vector Stroke Color").setValue(p.strokeColor);
      stroke.property("ADBE Vector Stroke Width").setValue(p.strokeWidth);
    }
    var pinGroup = contents.addProperty("ADBE Vector Group");
    pinGroup.name = "Pin";
    var pinPath = pinGroup.property("ADBE Vectors Group").addProperty("ADBE Vector Shape - Group");
    var path = pinPath.property("ADBE Vector Shape");
    var s = p.size * 0.15;
    var pShape = new Shape();
    pShape.vertices = [[0, -s], [s*0.5, 0], [0, s*2], [-s*0.5, 0]];
    pShape.inTangents = [[0,0],[0,0],[0,0],[0,0]];
    pShape.outTangents = [[0,0],[0,0],[0,0],[0,0]];
    pShape.closed = true;
    path.setValue(pShape);
    var pinFill = pinGroup.property("ADBE Vectors Group").addProperty("ADBE Vector Graphic - Fill");
    pinFill.property("ADBE Vector Fill Color").setValue([0.3, 0.3, 0.3]);
    var pinTransform = pinGroup.property("ADBE Vector Transform Group");
    pinTransform.property("ADBE Vector Position").setValue([0, -p.size/2]);
    var t0 = layer.inPoint;
    var pos = layer.property("ADBE Transform Group").property("ADBE Position");
    pos.setValueAtTime(t0, [comp.width/2, -p.size]);
    pos.setValueAtTime(t0 + p.duration * 0.5, [comp.width/2, comp.height/2 + 50]);
    pos.setValueAtTime(t0 + p.duration * 0.7, [comp.width/2, comp.height/2 - 20]);
    pos.setValueAtTime(t0 + p.duration, [comp.width/2, comp.height/2]);
    for (var k = 1; k <= pos.numKeys; k++) {
      pos.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    var rot = layer.property("ADBE Transform Group").property("ADBE Rotation");
    rot.setValueAtTime(t0, -20);
    rot.setValueAtTime(t0 + p.duration * 0.5, 10);
    rot.setValueAtTime(t0 + p.duration, 0);
